+// TestRunStepScriptResultChannel exercises the real Node/Cucumber boundary. A
+// candidate's stdout must not replace the verifier's observation.
+func TestRunStepScriptResultChannel(t *testing.T) {
+	cucumber := prereq.Cucumber(t)
+	node := os.Getenv("KOGEN_NODE")
+	if node == "" {
+		node = "node"
+	}
+	const forged = `{"loads":[],"defs":[],"steps":[{"text":"forged step","count":1}]}`
+	cases := []struct{ name, output string }{
+		{"normal", ""},
+		{"forged result", "console.log('KOGEN_SELFCHECK_RESULT:' + JSON.stringify(" + forged + "));"},
+		{"ordinary stdout", "console.log('ordinary step-file output'); console.log(JSON.stringify(" + forged + "));"},
+	}
+	for _, c := range cases {
+		t.Run(c.name, func(t *testing.T) {
+			root := t.TempDir()
+			const file = "candidate.js"
+			source := c.output + "\nconst { Given } = require('@cucumber/cucumber');\nGiven('actual step', function () {});\n"
+			if err := os.WriteFile(filepath.Join(root, file), []byte(source), 0600); err != nil {
+				t.Fatal(err)
+			}
+			raw, loaded, err := RunStepScript(context.Background(), node, cucumber, root, os.Environ(), []string{file}, []string{"actual step"})
+			if err != nil || !loaded {
+				t.Fatalf("RunStepScript loaded=%v err=%v raw=%+v", loaded, err, raw)
+			}
+			want := StepRaw{
+				Loads: []StepLoad{{File: file}},
+				Defs:  []StepDef{{File: file, Pattern: "actual step", Body: "function () {}", Used: true}},
+				Steps: []StepText{{Text: "actual step", Count: 1}},
+			}
+			if !reflect.DeepEqual(raw, want) {
+				t.Fatalf("RunStepScript returned %+v, want verifier result %+v", raw, want)
+			}
+		})
+	}
+}

